create or replace function public.reply_to_review(p_review_id uuid,p_reply text) returns public.reviews language plpgsql security definer set search_path = '' as $$ declare v_review public.reviews%rowtype; v_uid uuid := auth.uid(); v_reply text := nullif(trim(p_reply),''); begin if v_uid is null then raise exception 'Authentication required'; end if; if v_reply is null then raise exception 'Reply cannot be empty'; end if; if length(v_reply)>2000 then raise exception 'Reply is too long'; end if; select r.* into v_review from public.reviews r where r.id=p_review_id; if not found then raise exception 'Review not found'; end if; if not exists (select 1 from public.locations l join public.business_members bm on bm.business_id=l.business_id where l.id=v_review.location_id and bm.user_id=v_uid and bm.role=any(array['owner'::public.business_member_role,'admin'::public.business_member_role,'manager'::public.business_member_role])) then raise exception 'Not authorized to reply to this review'; end if; update public.reviews set business_reply=v_reply,business_replied_at=now(),updated_at=now() where id=p_review_id returning * into v_review; return v_review; end; $$; create or replace function public.verify_checkin(p_qr_code text,p_lat double precision default null,p_lng double precision default null) returns public.check_ins language plpgsql security definer set search_path = '' as $$ declare v_uid uuid := auth.uid(); v_qr public.qr_codes%rowtype; v_loc public.locations%rowtype; v_check public.check_ins%rowtype; v_distance double precision; begin if v_uid is null then raise exception 'Authentication required'; end if; select * into v_qr from public.qr_codes where code=p_qr_code and active=true limit 1; if not found then raise exception 'Invalid or inactive QR code'; end if; select * into v_loc from public.locations where id=v_qr.location_id and is_active=true and verification_status='verified'; if not found then raise exception 'Location is not currently available for check-in'; end if; if p_lat is not null and p_lng is not null and v_loc.geom is not null then v_distance:=extensions.st_distance(v_loc.geom,extensions.st_setsrid(extensions.st_makepoint(p_lng,p_lat),4326)::extensions.geography); if v_distance>coalesce(v_loc.geofence_radius_m,250) then raise exception 'You are too far from this location'; end if; end if; if exists(select 1 from public.check_ins where user_id=v_uid and location_id=v_loc.id and checked_in_at>now()-interval '30 minutes') then raise exception 'Already checked in here recently'; end if; insert into public.check_ins(user_id,location_id,qr_code_id,latitude,longitude,distance_meters,verification_method) values(v_uid,v_loc.id,v_qr.id,p_lat,p_lng,v_distance,'qr') returning * into v_check; return v_check; end; $$; revoke execute on function public.reply_to_review(uuid,text) from anon; revoke execute on function public.verify_checkin(text,double precision,double precision) from anon; grant execute on function public.reply_to_review(uuid,text) to authenticated; grant execute on function public.verify_checkin(text,double precision,double precision) to authenticated;
